fn main() -> Int {
  let v = Vec[Int]();
  v.push(5); v.push(12); v.push(8); v.push(20); v.push(15); v.push(3); v.push(25);

  var sum = 0;
  var count = 0;
  for n in v {
    if n > 10 {
      if count < 3 {
        sum = sum + n * 2;
        count = count + 1;
      }
    }
  }
  return sum;
}
